import sys
f=sys.argv[1]; s=open(f,encoding='utf-8').read()
def sub(a,b,n=1):
    global s; assert s.count(a)==n,(a[:90],s.count(a)); s=s.replace(a,b)
sub("'\"ผมเองยังต้องเพ่งเลยครับ ไม่ใช่ตาคุณปู่หรอก ฉลากมันเล็กเกินไป\"'","'\"ฉลากตัวเล็กจริงๆ ครับ\" เขาพูด\\nแล้วขยับแว่นของตัวเองเพื่ออ่านอีกครั้ง'")
sub("'เด็กคนนั้นหยิบของออกจากกระเป๋า\\nยาพ่นสีฟ้า กับกระบอกใสยาวราวหนึ่งคืบ'","'เด็กคนนั้นหยิบกระบอกช่วยสูดออกจากกระเป๋า\\nวางไว้ข้างยาพ่นสีฟ้าของผม'")
sub("'ไม่ขม ไม่ไอ\\nหลายปีที่ผมสู้กับหลอดสีฟ้านี่ มันแค่ต้องการกระบอกพลาสติกหนึ่งอัน'","'คราวนี้ผมสูดได้ตามที่เขาบอก\\nยังต้องฝึกอีก แต่ผมเริ่มเข้าใจวิธีให้ยาเข้าปอด'")
sub("หมุนฐานใสครึ่งรอบ จนดังคลิก\"'","หมุนฐานจนได้ยินเสียงคลิก\"'")
sub("'เขาไม่ได้พูดว่า จะทดสอบผม\\nเขาพูดว่า จะตรวจว่าตัวเขาเองสอนรู้เรื่องไหม'","'เขาไม่ได้พูดว่าต้องสอบผ่าน\\nผมเลยไม่กลัวว่าจะทำผิด'")
sub("S.tbErr?'ผมพลาดไป '+S.tbErr+' ครั้ง เขาไม่ได้นับ\\nผมนับเอง':","S.tbErr?(S.tbErr>1?'ผมพลาดหลายครั้ง':'ผมพลาดไปหนึ่งครั้ง')+'\\nเขาไม่ได้ถอนหายใจสักครั้ง':")
sub("'\"คุณปู่ครับ วันที่คุณอาเหมยเข้าเวรดึก เช้าวันนั้นเป็นยังไงบ้างครับ\"\\nเขาไม่ได้ถามว่า ลืมกินยาหรือเปล่า'","'\"วันที่อาเหมยเข้าเวรดึก ตอนเช้าคุณปู่ทำยังไงบ้างครับ\"\\nเขาไม่ได้ถามว่า ลืมยาหรือเปล่า'")
sub("await say(['\"ผมลืม\" ผมได้ยินเสียงตัวเอง\\n\"วันที่ไม่มีใครโทรมา ผมลืม'+(anyDbl?' แล้วผมก็กินรวมทีเดียวตอนกลางคืน\"':' แล้วก็ปล่อยมันข้ามไป\"'),'\"แล้วเมื่อคืน… ผมล้มในห้องน้ำ\"\\nห้องเงียบ ได้ยินแต่เสียงพัดลม',",
    "await say(['\"ผมลืม\" ผมได้ยินเสียงตัวเอง\\n\"วันที่ไม่มีใครโทรมา ผมลืม\"',anyDbl?'\"แล้วผมก็กินยารวมกันทีเดียวตอนกลางคืน\"':'\"ผมข้ามยาเช้าไป\"','\"เมื่อคืนผมล้มในห้องน้ำด้วย\"\\nครั้งนี้ผมพูดได้เต็มเสียง',")
sub("'\"ไม่มีใครส่งคุณปู่ไปไหนทั้งนั้นครับ\" เภสัชกรเฉินพูดช้าๆ\\n\"เรามาเพื่อให้คุณปู่อยู่ห้องนี้ได้นานที่สุด กับเจ้าดำ\"'","'\"ไม่มีใครจะตัดสินใจเรื่องที่อยู่แทนคุณปู่จากคำพูดวันนี้ครับ\" เภสัชกรเฉินว่า','\"แต่เรื่องล้มต้องประเมินความปลอดภัย\\nเราจะคุยทางเลือกกับคุณปู่ทุกขั้น\"'")
sub("await say(['อาเหมยเดินมานั่งลงข้างผม จับแขนผมไว้สองมือ\\n\"วันที่หนูเข้าเวรดึก","await say(['อาเหมยเดินมานั่งลงข้างผม จับแขนผมไว้สองมือ','\"วันที่หนูเข้าเวรดึก")
sub("'เธอรู้เรื่องกริ่งที่สอง\\nเธอรู้มาตลอด'","'ผมไม่เคยบอกเรื่องกริ่งที่สอง\\nแต่เธอกลับพูดได้ถูก'")
sub("วางไว้ข้างโทรศัพท์สีแดง\\nเขาไม่ได้เชื่อผม และเขาไม่ได้บังคับผม ผมไม่เคยเจอสองอย่างนี้พร้อมกัน'","วางไว้ข้างโทรศัพท์สีแดง','เขาไม่ได้เขียนว่า \"ไม่ร่วมมือ\"\\nเขาทิ้งเบอร์ไว้ และบอกว่าจะกลับมาฟังอีก'")
sub("'ลืมยาเช้า กินรวมกับยาก่อนนอน ยาจะได้ไม่เสียของ'","'ลืมยาเช้า กินรวมกับยาก่อนนอน'")
sub("'พ่นอันสีฟ้าไว้ก่อนทุกเช้า กันหอบ'","'พ่นอันสีฟ้าไว้ก่อนทุกเช้า'")
sub("await say(['\"ยาเบาหวานตัวนั้น ถ้ากินสองมื้อรวมกัน น้ำตาลจะตกตอนกลางดึกครับ เหงื่อแตก มือสั่น ใจสั่น หน้ามืด\\nนึกได้ตอนค่ำ ให้ข้ามไปเลย พรุ่งนี้เริ่มใหม่\"',","await say(['\"ยาเบาหวานตัวนี้กินซ้ำอาจทำให้น้ำตาลต่ำได้ครับ\\nคืนที่เหงื่อแตก มือสั่น ใจสั่น ต้องประเมินอาการและน้ำตาล ไม่ควรปล่อยผ่าน\"','\"ส่วนยาที่ลืม เราจะเขียนวิธีจัดการแยกแต่ละตัวให้ชัดครับ\\nอย่ากินสองมื้อรวมกัน\"',")
sub("'\"ยาจะเหลือน้อยกว่านี้ครับ ผมจะเขียนถึงคุณหมอทั้งสี่ท่าน\\nให้แต่ละท่านรู้ ว่ามีอีกสามท่าน\"'","'\"ผมจะเขียนถึงคุณหมอทั้งสี่ท่านครับ ให้เห็นยาทุกซอง\\nถ้าคุณหมอตกลงปรับยา เราจะช่วยกันจัดกล่องใหม่\"'")
sub("['\"อาทิตย์หน้าผมมาใหม่นะครับ\"\\nผมเกือบถามว่า กี่โมง จะได้นั่งรอ','ประตูปิด\\nห้องกลับมาสิบหกตารางเมตรเท่าเดิม แต่ไม่เงียบเท่าเดิม']","['\"วันศุกร์หน้าเรามาติดตามกันอีกครั้งนะครับ\"\\nผมอยากถามว่า กี่โมง','สุดท้ายผมถาม\\nเขาหยุดจด แล้วเปิดนัดให้ผมดู','ประตูปิด\\nห้องยังมีขนาดเท่าเดิม ทุกอย่างอยู่ที่เดิม','ผมมองที่พื้นตรงที่เด็กคนนั้นนั่ง\\nตรงนั้นไม่มีอะไรเปลี่ยนไปเลย']")
sub("['สิบวินาที\\nเจ้าดำเหยียบเท้าผมสองครั้ง ผมเหยียบเท้ามันหนึ่งครั้ง','แม่\\nผมมาช้าไปเจ็ดสิบสี่ปี','แต่ผมมาแล้ว']","['สิบวินาที\\nผมโยกไหล่เบาๆ มือหนึ่งจับโต๊ะไว้','เจ้าดำเอาจมูกมาแตะหลังมือ\\nเหมือนบอกว่า ไม่ต้องฝืน','ผมไม่ฝืน\\nสิบวินาทีก็นับ']")
sub("'คืนนี้ผมใช้อันสีเขียวก่อนนอนอีกรอบ ไม่ใช่เพราะถึงเวลา\\nผมแค่อยากหมุนให้ดังคลิก ให้แน่ใจว่ายังจำได้'","'ก่อนนอนผมหยิบอันสีเขียวขึ้นมาดู\\nอยากลองให้ดังคลิกอีก แต่กระดาษเขียนว่าใช้ตอนเช้า ผมจึงวางคืน'")
sub("'ผู้มาเยี่ยม: สามคน อยู่หนึ่งชั่วโมงครึ่ง','ถูกขออนุญาต: '+(5)+' ครั้ง ในห้องของผมเอง'","'ผู้มาเยี่ยม: สองคน กับอาเหมย อยู่หนึ่งชั่วโมงครึ่ง','ถูกขออนุญาต: หลายครั้ง ในห้องของผมเอง'")
sub("'ยาพ่นสีเขียว: หมุน เปิด กด'+((S.tbErr+S.sumErr)?' (พลาด '+(S.tbErr+S.sumErr)+' ครั้ง ไม่มีใครดุ)':' (ไม่พลาด)')","'ยาพ่นสีเขียว: หมุน เปิด กด\\n'+((S.tbErr+S.sumErr)?'พลาดอยู่'+((S.tbErr+S.sumErr)>1?'หลาย':'หนึ่ง')+'ครั้ง ไม่มีใครดุ':'ทำได้ครบ มีคนรอดูจนจบ')")
sub("'แม่ครับ\\nวันนี้มีคนคุกเข่าลงคุยกับผม','พรุ่งนี้วันเสาร์', '', 'สิบวินาทีก็นับนะ เจ้าลูกดื้อ\\nแม่รอมาเจ็ดสิบสี่ปี รออีกนิดก็ได้'","'แม่ครับ วันนี้มีคนถามว่าผมอยากทำอะไร\\nแล้วเขารอฟังจนจบ','พรุ่งนี้วันเสาร์', '', 'เจ้าชอบบอกว่าไม่เป็นไร\\nวันนี้มีใครถามต่อหรือเปล่าล่ะ'")
open(f,'w',encoding='utf-8').write(s); print('d4b ok')
